insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"HOME_BURST","title":"¿El local anota 6 o más y el visitante se queda en 3 o menos?","description":"Se corrige con el marcador final.","category":"resultado","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"and","rules":[{"op":"home_gte","n":6},{"op":"away_lte","n":3}]},"priority":0,"cooldown":2,"tags":["resultado"]},{"code":"AWAY_BURST","title":"¿El visitante anota 6 o más y el local se queda en 3 o menos?","description":"Se corrige con el marcador final.","category":"resultado","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"and","rules":[{"op":"away_gte","n":6},{"op":"home_lte","n":3}]},"priority":0,"cooldown":2,"tags":["resultado"]},{"code":"HOME_EXACT_3","title":"¿El local anota exactamente 3?","description":"Se corrige con el marcador final.","category":"dificultad","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"home_eq","n":3},"priority":0,"cooldown":2,"tags":["dificultad"]},{"code":"AWAY_EXACT_3","title":"¿El visitante anota exactamente 3?","description":"Se corrige con el marcador final.","category":"dificultad","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"away_eq","n":3},"priority":0,"cooldown":2,"tags":["dificultad"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;